<script setup lang="ts">
import {computed,ref} from 'vue';
import Icon from '../../shared/Icon.vue';
import type {Topic} from '../../shared/api/topics';
const props=withDefaults(defineProps<{mode:'create'|'update'|'delete'|'assign';name:string;description:string;selected:string;topics:readonly Topic[];meetingNames:readonly string[];pending:boolean;busy:boolean;composing:boolean;state:string;error:string|null;deleteCount?:number|null}>(),{deleteCount:0});
const emit=defineEmits<{'update:name':[value:string];'update:description':[value:string];'update:selected':[value:string];'update:composing':[value:boolean];submit:[];retry:[];discard:[];close:[];create:[];edit:[topic:Topic];delete:[topic:Topic]}>();
const dialog=ref<HTMLDialogElement>(),locked=computed(()=>props.pending||props.busy),batch=computed(()=>props.mode==='assign'&&props.meetingNames.length>1),blocked=computed(()=>props.mode==='delete'&&!props.pending&&(props.deleteCount??0)>0),heading=computed(()=>props.mode==='create'?'新建会议专题':props.mode==='update'?'修改专题':props.mode==='delete'?blocked.value?'无法删除专题':props.deleteCount===null&&!props.pending?'读取专题状态':'删除空专题':batch.value?`批量调整专题（${props.meetingNames.length} 场会议）`:'调整会议专题');
function close(event?:Event){event?.preventDefault();if(props.mode==='assign'||!props.busy)emit('close');}
defineExpose({show:()=>dialog.value?.showModal(),close:()=>dialog.value?.close()});
</script>
<template><dialog ref="dialog" class="mask topic-dialog-root" :aria-label="heading" @cancel="close" @click="event=>{if(event.target===event.currentTarget)close();}"><div class="modal topic-dialog">
 <header class="modal-h"><h3 class="m-t">{{heading}}</h3><button class="m-x" aria-label="关闭" :disabled="mode!=='assign'&&busy" @click="close()"><Icon name="x" :size="18"/></button></header>
 <div class="modal-b">
 <template v-if="mode==='create'||mode==='update'"><div class="field"><label for="topic-name">专题名称<span class="req" aria-hidden="true">*</span></label><input id="topic-name" class="input" required aria-required="true" :value="name" maxlength="255" :readonly="locked" placeholder="例如：2026年权益投资经营复盘" @input="emit('update:name',($event.target as HTMLInputElement).value)" @compositionstart="emit('update:composing',true)" @compositionend="emit('update:composing',false)"/></div><div class="field"><label for="topic-description">专题说明</label><textarea id="topic-description" class="input" rows="2" :value="description" maxlength="4096" :readonly="locked" placeholder="一句话说明归集范围" @input="emit('update:description',($event.target as HTMLTextAreaElement).value)" @compositionstart="emit('update:composing',true)" @compositionend="emit('update:composing',false)"/></div><div v-if="mode==='create'" class="banner info" style="margin:0"><Icon name="layers" :size="15"/> 专题仅支持一级结构，用于在「我的会议」内归集连续会议，不具有独立权限。</div></template>
 <template v-else-if="mode==='delete'"><div v-if="blocked" class="banner warn" style="margin:0"><Icon name="alert" :size="16"/> 专题「{{name}}」下仍有 {{deleteCount}} 场会议。删除已有会议的专题只会解除归集关系、不删除会议，请先将会议移出该专题。</div><p v-else-if="deleteCount===null&&!pending" role="status">正在核实专题内的会议…</p><template v-else>确定删除专题「{{name||'所选专题'}}」吗？该操作仅删除归集入口。</template></template>
 <template v-else>
  <label v-if="batch" class="radio-row" :class="{sel:selected==='__keep'}"><input class="topic-choice" type="radio" name="assignment-topic" value="__keep" :checked="selected==='__keep'" :disabled="locked" @change="emit('update:selected','__keep')"/><span class="radio-dot" aria-hidden="true"></span>移动到所选专题：</label>
  <template v-else><div class="topic-assignment-heading"><span class="small muted">会议：{{meetingNames.join('、')}}</span><button class="btn sm" :disabled="locked" @click="emit('create')"><Icon name="plus" :size="13"/> 快速创建一级专题</button></div><label class="radio-row" :class="{sel:selected===''}"><input class="topic-choice" type="radio" name="assignment-topic" value="" :checked="selected===''" :disabled="locked" @change="emit('update:selected','')"/><span class="radio-dot" aria-hidden="true"></span>暂不归入专题</label></template>
  <div v-for="topic in topics" :key="topic.id" class="radio-row topic-option" :class="{sel:selected===topic.id}" role="group" :aria-label="'专题：'+topic.name">
   <label class="topic-option-label"><input class="topic-choice" type="radio" name="assignment-topic" :value="topic.id" :checked="selected===topic.id" :disabled="locked" @change="emit('update:selected',topic.id)"/><span class="radio-dot" aria-hidden="true"></span><span class="topic-option-copy"><template v-if="batch">{{topic.name}}</template><template v-else><span class="b">{{topic.name}}</span><span class="small muted">{{topic.description}}</span></template></span></label>
   <div class="topic-option-actions"><button class="btn sm ghost topic-icon" :disabled="locked" :aria-label="'编辑专题：'+topic.name" title="编辑专题" @click="emit('edit',topic)"><Icon name="edit" :size="14"/></button><button class="btn sm ghost danger topic-icon" :disabled="locked" :aria-label="'删除专题：'+topic.name" title="删除专题" @click="emit('delete',topic)"><Icon name="trash" :size="14"/></button></div>
  </div>
  <label v-if="batch" class="radio-row" :class="{sel:selected===''}"><input class="topic-choice" type="radio" name="assignment-topic" value="" :checked="selected===''" :disabled="locked" @change="emit('update:selected','')"/><span class="radio-dot" aria-hidden="true"></span>移出专题（不归入任何专题）</label>
 </template>
 <p v-if="error" class="banner error" role="alert">{{error}}</p>
 </div><footer class="modal-f"><button v-if="blocked" class="btn primary" @click="close()">知道了</button><template v-else><button v-if="mode!=='assign'&&pending&&['CONFLICT','REJECTED'].includes(state)" class="btn" :disabled="busy" @click="emit('discard')">放弃已拒绝的原请求</button><button class="btn" :disabled="mode!=='assign'&&busy" @click="close()">取消</button><button v-if="mode==='assign'" class="btn primary" :aria-busy="busy" @click="pending?emit('retry'):emit('submit')">{{batch?'应用':'确定'}}</button><button v-else-if="pending||mode!=='delete'||deleteCount!==null" class="btn" :class="mode==='delete'?'danger':'primary'" :aria-busy="busy" :aria-label="pending?'重试原专题请求':undefined" :disabled="busy||composing||(pending&&!['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(state))" @click="pending?emit('retry'):emit('submit')">{{mode==='create'?'创建专题':mode==='delete'?'删除':'保存'}}</button></template></footer>
</div></dialog></template>
<style scoped>.topic-dialog-root{inset:0;border:0;padding:24px;margin:0;width:100vw;height:100dvh;max-width:none;max-height:none;color:var(--text)}.topic-dialog-root:not([open]){display:none}.topic-dialog-root::backdrop{background:transparent}.topic-dialog .input{width:100%}.m-t{margin:0}.topic-choice{position:absolute;width:1px;height:1px;clip-path:inset(50%);overflow:hidden;padding:0;margin:0;border:0}.topic-choice:focus-visible + .radio-dot{outline:1px solid var(--navy);outline-offset:2px}.req{color:var(--red)}</style>
<style scoped>
.topic-assignment-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.topic-assignment-heading>span{min-width:0;overflow-wrap:anywhere}.topic-assignment-heading>.btn{flex-shrink:0}.topic-option-label{display:flex;align-items:center;gap:8px;flex:1;min-width:0;cursor:pointer}.topic-option-copy{min-width:0;overflow-wrap:anywhere}.topic-option-copy>span{display:block}.topic-option-actions{display:flex;gap:4px;flex-shrink:0}.topic-option-actions>.topic-icon{width:28px;height:28px;padding:4px}
</style>
